#include "(CurrentProject)/vTools/vadmin.js"
importApi("AdminApi");


// Verificamos los datos introducidos
var continuar=true;
// Coinciden las passwords?
if (theRoot.varToString("PASSWORD")!=theRoot.varToString("PASSWORD_REPETIDA")) {
	alert(tr("sygemat_corralon_app/ERR_PWD_DIF"));
	continuar=false;
}

// Ha dejado en blanco alguno de los campos requeridos
if (theRoot.varToString("NAME")==="") {
	alert("El campo nombre es obligatorio");
	continuar=false;
}

if (continuar) {
	var idUser = theRoot.varToInt("ID");
	// Obtenemos el root del formulario de grupos para acceder a los controles listbox
	var rootGruposForm = theRoot.dataView().relativeControl("PESTAÑADOR.GRUPOS").root();
	var lbDerecho = rootGruposForm.dataView().control("LB_DERECHO");

	// Convertimos los grupos seleccionados por el usuario a cadena separados por separador
	var grupos=[];
	for (var i=0; i<lbDerecho.count; i++)
		grupos.push(lbDerecho.itemData(i));
	grupos=grupos.join(vAdmin.separador);

	var password=undefined;
	if (theRoot.varToBool("PASSWORD_EDITADA"))
		password=theRoot.varToString("PASSWORD");
	// Es una modificación?
	if (idUser) 
		var retorno=vAdmin.user.update(idUser, theRoot.varToString("NAME"), theRoot.varToString("FULLNAME"), password, theRoot.varToBool("CB_SUPERVISOR"), theRoot.varToBool("CB_CUENTA_BLOQUEADA"), 
						theRoot.varToBool("CB_CUENTA_DESACTIVADA"), theRoot.varToBool("CB_DEBE_CAMBIAR_PASSWORD"), theRoot.varToBool("CB_PASSWORD_NO_CADUCA"), grupos)
	else
		var retorno=vAdmin.user.add(theRoot.varToString("NAME"), theRoot.varToString("FULLNAME"), password, theRoot.varToBool("CB_SUPERVISOR"), theRoot.varToBool("CB_CUENTA_BLOQUEADA"), 
						theRoot.varToBool("CB_CUENTA_DESACTIVADA"), theRoot.varToBool("CB_DEBE_CAMBIAR_PASSWORD"), theRoot.varToBool("CB_PASSWORD_NO_CADUCA"), grupos);
	if (retorno.result==1){
		//theRoot.dataView().closeForm()
		theRoot.setVar("CONTINUAR",1);
	}else{
		theRoot.setVar("CONTINUAR",0);
		alert(retorno.text);
	}		

}

var lbDerecho = theRoot.dataView().control("PESTAÑADOR").form(0).control("LB_DERECHO");

var cadena = ""
for(var i = 0; i < lbDerecho.count; i++){
		cadena += lbDerecho.itemText(i) + ";#;";
}
theRoot.setVar("GRUPOS", cadena);

importApi("AdminApi");


var idUser = theRoot.varToInt("ID");

if (idUser!=0) {
	// Es modificación de usuario
	var user = new VUser();
	if (theServerAdmin.getUserById(idUser, user)) {
		theRoot.setVar("NAME", user.name());
		// Estamos modificando, así que inhabilitamos la modificación del campo Name
		theRoot.dataView().control("ED_NAME").setEnabled(false);
		theRoot.setVar("FULLNAME", user.fullName());
		theRoot.setVar("CB_SUPERVISOR", user.isAdministrator());
		theRoot.setVar("CB_CUENTA_DESACTIVADA", user.isAccountDisabled());
		theRoot.setVar("CB_CUENTA_BLOQUEADA", user.isAccountBlocked());
		theRoot.setVar("CB_DEBE_CAMBIAR_PASSWORD", user.changePasswordNextConnect());
		theRoot.setVar("CB_PASSWORD_NO_CADUCA", user.passwordNotExpire());
		theRoot.setVar("PASSWORD", "12345678901234567890");
		theRoot.setVar("PASSWORD_REPETIDA", "12345678901234567890");
		theRoot.dataView().updateControls();
	} else {
		alert(tr("sygemat_corralon_app/ERR_LOC_USR"));
	}
}
